"""Add topic-linked Y12 IB Maths pages using the exported GDC trainer metadata."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent.parent
manifest=json.loads((ROOT/'activities/y12/maths/gdc-trainer/trainer-manifest.json').read_text())
esc=html.escape
for i,topic in enumerate(manifest['topics']):
 folder=ROOT/'activities/y12/maths'/topic['id'];folder.mkdir(parents=True,exist_ok=True)
 symbol=['GDC','xⁿ','f(x)','△','Σ','∫'][i]
 cover=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 260"><rect width="360" height="260" rx="20" fill="#244b43"/><rect x="128" y="30" width="145" height="203" rx="18" fill="#1a3440" stroke="#809e96" stroke-width="2"/><rect x="146" y="49" width="110" height="63" rx="4" fill="#c5dab8"/><text x="201" y="91" fill="#315d4b" font-family="system-ui" font-size="30" text-anchor="middle">{esc(symbol)}</text>{''.join(f'<rect x="{148+n%4*27}" y="{130+n//4*25}" width="19" height="15" rx="3" fill="{["#bed2c3","#d9b082","#82b5a8"][n%3]}"/>' for n in range(16))}<text x="70" y="124" fill="#edceaa" text-anchor="middle" font-size="18" font-family="system-ui">Y12</text><text x="70" y="151" fill="#b4d3be" text-anchor="middle" font-size="13" font-family="system-ui">MATHS</text></svg>'''
 (folder/'cover.svg').write_text(cover)
 nav=''.join(f'<a data-gdc-topic-link href="../{esc(t["id"])}/"'+(' aria-current="page"' if t==topic else '')+f'>{esc(t["name"])}</a>' for t in manifest['topics'])
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(topic['name'])} | Y12 IB Maths | Learning Lab</title><meta name="description" content="{esc(topic['description'])}"><link rel="icon" type="image/png" href="../../../../assets/brand/learning-lab-logo.png?v=1"><link rel="stylesheet" href="../../../../platform.css"><link rel="stylesheet" href="../../../../assets/brand/brand.css?v=1"><link rel="stylesheet" href="../../../../assets/gdc/topics.css?v=1"><link rel="stylesheet" href="../../../../assets/desktop-layout.css?v=desktop-1"><script type="module" src="../../../../assets/gdc/topics.js?v=1"></script></head><body data-gdc-topic="{esc(topic['id'])}"><a class="skip-link" href="#guided-skills">Skip to calculator exercises</a><header class="site-header"><a class="wordmark" href="../../../../index.html"><img class="brand-logo" src="../../../../assets/brand/learning-lab-logo.png" width="46" height="46" alt=""><span>learning<span class="wordmark-light">lab</span><small>A PLACE FOR CURIOUS MINDS</small></span></a><nav><a href="../../../../index.html#/years/y12/maths">Y12 Maths</a><a href="../gdc-trainer/?mode=free&topic={esc(topic['id'])}">Free calculator</a></nav></header><main><nav class="breadcrumbs" aria-label="Breadcrumb"><ol><li><a href="../../../../index.html">Home</a></li><li><a href="../../../../index.html#/years/y12">Y12</a></li><li><a href="../../../../index.html#/years/y12/maths">Maths</a></li><li><span aria-current="page">{esc(topic['name'])}</span></li></ol></nav><section class="gdc-topic-hero"><div><div class="eyebrow">YEAR 12 · IB MATHEMATICS · CALCULATOR SKILLS</div><h1>{esc(topic['name'])}</h1><p>{esc(topic['description'])}</p><p>Choose a worked calculator exercise. The trainer highlights the next physical key and advances when you use it correctly. Then repeat in free practice.</p></div><img src="cover.svg" width="360" height="260" alt="Calculator illustration for {esc(topic['name'])}"></section><nav class="gdc-topic-nav" aria-label="Maths topics">{nav}</nav><section class="gdc-course-bar"><div><h2>Choose your IB course</h2><p>Show the relevant skills for Analysis and Approaches or Applications and Interpretation.</p></div><label for="gdc-course">Course and level<select id="gdc-course"><option value="all">All IB courses</option>{''.join(f'<option>{esc(c)}</option>' for c in manifest['courses'])}</select></label></section><section id="guided-skills" aria-labelledby="guided-title"><div class="section-intro"><div><div class="eyebrow">01 · GUIDED SIMULATOR PRACTICE</div><h2 id="guided-title">Use the calculator, one key at a time.</h2></div><p id="gdc-count" role="status"></p></div><div class="gdc-exercise-grid" id="gdc-exercises"><p role="status">Loading the calculator exercises…</p></div></section><section class="gdc-manual-section" aria-labelledby="manual-title"><div class="eyebrow">02 · CALCULATOR REFERENCE</div><h2 id="manual-title">Related manual procedures</h2><p>The source trainer contains 42 skill pages. Reviewed procedures and outlines awaiting physical-device verification are labelled separately. A guided simulator example does not certify every menu on a physical calculator.</p><div id="gdc-manual"></div></section><section class="gdc-practice-note"><h2>Practise, then explain.</h2><p>Predict the result, follow the highlighted keys and interpret the calculator’s answer. This is practice: calculator actions are not sent to the teacher dashboard. These calculator activities support the examples and explanations in your class lessons.</p><a id="gdc-free-link" href="../gdc-trainer/?mode=free&topic={esc(topic['id'])}">Open the free calculator →</a></section><noscript><p>Enable JavaScript to filter and open the guided exercises.</p><a href="../gdc-trainer/">Open GDC trainer</a></noscript></main><footer class="site-footer"><a class="footer-brand" href="../../../../index.html"><img class="brand-logo" src="../../../../assets/brand/learning-lab-logo.png" width="34" height="34" alt="">learning<span>lab</span></a><p>Y12 Maths · Topic-linked GDC training</p><a href="../../../../index.html#/years/y12/maths">All maths topics →</a></footer></body></html>'''
 (folder/'index.html').write_text(page)
p=ROOT/'catalog.json';catalog=json.loads(p.read_text());year=next(y for y in catalog['years'] if y['id']=='y12');subject=next((s for s in year['subjects'] if s['id']=='maths'),None)
if subject is None:subject={'id':'maths','name':'Maths','description':'IB Mathematics: topic-linked GDC practice for AA/AI at SL and HL.','topics':[]};year['subjects'].append(subject)
for t in manifest['topics']:
 entry={'id':t['id'],'name':t['name'],'description':t['description'],'primaryActivity':'gdc-'+t['id'],'appTitle':t['name'],'activities':[{'id':'gdc-'+t['id'],'title':t['name']+': GDC practice','description':t['description'],'format':'Guided calculator practice','duration':'Choose a calculator skill','href':f'activities/y12/maths/{t["id"]}/','image':f'activities/y12/maths/{t["id"]}/cover.svg'}]}
 old=next((i for i,x in enumerate(subject['topics']) if x['id']==t['id']),None)
 if old is None:subject['topics'].append(entry)
 else:subject['topics'][old]=entry
p.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
print('Built six Y12 Maths entry pages: essentials plus the five IB topic groups.')
